#!/bin/bash
# The pictures and fonts of the bloom GRUB theme, in the {{name}} colors. Generated by
# `facet theme`; edit templates/grub/frameshell/images.sh instead.
#
#   bash images.sh <folder>    writes every *.png and *.pf2 theme.txt names into <folder>
#
# `facet grub` runs it and copies the results to /boot with theme.txt. The pictures are
# drawn here with gawk (part of every Arch install), so no image tool is needed; the fonts
# come from Rubik and the theme's mono font through grub-mkfont.
set -euo pipefail

out=${1:?usage: images.sh <folder>}
mkdir -p "$out"

surface={{tones.surface|bare}}
primary={{tones.primary|bare}}
high={{tones.high|bare}}

# draw <file> <width> <height> <x> <y> <layer>...: one PNG of the given size, showing the
# part of a larger drawing that starts at x, y (so the slices of one shape line up). Each
# layer is painted over the ones before it, edges smoothed:
#   "rrggbb disc cx cy r"              a filled circle
#   "rrggbb ring cx cy r w"            a circle line w wide around radius r
#   "rrggbb arch cx cy r w"            the upper half of that ring
#   "rrggbb rect x0 y0 x1 y1 r"        a rectangle with corners of radius r
#   "rrggbb line x0 y0 x1 y1 w"        a line w wide with round ends
#   "- <shape> …"                      cuts the shape out of what is painted so far
draw() {
    local file=$1 w=$2 h=$3 ox=$4 oy=$5
    shift 5
    local IFS=';'
    LC_ALL=C gawk -b -v out="$file" -v w="$w" -v h="$h" -v ox="$ox" -v oy="$oy" -v spec="$*" '
function abs(v) { return v < 0 ? -v : v }
function cover(d) { d = 0.5 - d; return d < 0 ? 0 : d > 1 ? 1 : d }
function dist(i, x, y,   t, dx, dy, cx, cy, qx, qy, mx, my, m, r, len, k) {
    t = S[i]
    if (t == "disc") {
        dx = x - P[i, 1]; dy = y - P[i, 2]
        return sqrt(dx * dx + dy * dy) - P[i, 3]
    }
    if (t == "ring" || t == "arch") {
        if (t == "arch" && y > P[i, 2]) return 1e9
        dx = x - P[i, 1]; dy = y - P[i, 2]
        return abs(sqrt(dx * dx + dy * dy) - P[i, 3]) - P[i, 4] / 2
    }
    if (t == "rect") {
        cx = (P[i, 1] + P[i, 3]) / 2; cy = (P[i, 2] + P[i, 4]) / 2; r = P[i, 5]
        qx = abs(x - cx) - (P[i, 3] - P[i, 1]) / 2 + r
        qy = abs(y - cy) - (P[i, 4] - P[i, 2]) / 2 + r
        mx = qx > 0 ? qx : 0; my = qy > 0 ? qy : 0
        m = qx > qy ? qx : qy; m = m < 0 ? m : 0
        return sqrt(mx * mx + my * my) + m - r
    }
    if (t == "line") {
        dx = P[i, 3] - P[i, 1]; dy = P[i, 4] - P[i, 2]; len = dx * dx + dy * dy
        k = len > 0 ? ((x - P[i, 1]) * dx + (y - P[i, 2]) * dy) / len : 0
        k = k < 0 ? 0 : k > 1 ? 1 : k
        mx = x - P[i, 1] - k * dx; my = y - P[i, 2] - k * dy
        return sqrt(mx * mx + my * my) - P[i, 5] / 2
    }
    return 1e9
}
function byte(v) { v = int(v + 0.5); return v < 0 ? 0 : v > 255 ? 255 : v }
function push(v) { C[m++] = v }
function push32(v) { push(and(rshift(v, 24), 255)); push(and(rshift(v, 16), 255)); push(and(rshift(v, 8), 255)); push(and(v, 255)) }
function put32(v) { printf "%c%c%c%c", and(rshift(v, 24), 255), and(rshift(v, 16), 255), and(rshift(v, 8), 255), and(v, 255) > out }
# Writes C[0..m) (type and data) as one chunk with its length and CRC
function chunk(   j, c) {
    put32(m - 4)
    c = 4294967295
    for (j = 0; j < m; j++) {
        printf "%c", C[j] > out
        c = xor(T[and(xor(c, C[j]), 255)], rshift(c, 8))
    }
    put32(xor(c, 4294967295))
    m = 0
}
BEGIN {
    n = split(spec, L, ";")
    for (i = 1; i <= n; i++) {
        k = split(L[i], f, " ")
        if (f[1] == "-") E[i] = 1
        else { E[i] = 0; R[i] = strtonum("0x" substr(f[1], 1, 2)); G[i] = strtonum("0x" substr(f[1], 3, 2)); B[i] = strtonum("0x" substr(f[1], 5, 2)) }
        S[i] = f[2]
        for (j = 3; j <= k; j++) P[i, j - 2] = f[j] + 0
    }
    # Scanlines: filter byte 0, then RGBA; colors kept premultiplied while layering
    nr = 0
    for (y = 0; y < h; y++) {
        D[nr++] = 0
        for (x = 0; x < w; x++) {
            px = x + ox + 0.5; py = y + oy + 0.5
            cr = cg = cb = ca = 0
            for (i = 1; i <= n; i++) {
                a = cover(dist(i, px, py))
                if (a <= 0) continue
                if (E[i]) { cr *= 1 - a; cg *= 1 - a; cb *= 1 - a; ca *= 1 - a; continue }
                cr = R[i] * a + cr * (1 - a); cg = G[i] * a + cg * (1 - a); cb = B[i] * a + cb * (1 - a)
                ca = a + ca * (1 - a)
            }
            if (ca > 0) { cr /= ca; cg /= ca; cb /= ca }
            D[nr++] = byte(cr); D[nr++] = byte(cg); D[nr++] = byte(cb); D[nr++] = byte(ca * 255)
        }
    }
    for (i = 0; i < 256; i++) {
        c = i
        for (k = 0; k < 8; k++) c = and(c, 1) ? xor(3988292384, rshift(c, 1)) : rshift(c, 1)
        T[i] = c
    }
    printf "%c%c%c%c%c%c%c%c", 137, 80, 78, 71, 13, 10, 26, 10 > out
    m = 0
    push(73); push(72); push(68); push(82); push32(w); push32(h)
    push(8); push(6); push(0); push(0); push(0)
    chunk()
    # zlib without compression: stored blocks of at most 65535 bytes, then Adler-32
    push(73); push(68); push(65); push(84); push(120); push(1)
    for (pos = 0; pos < nr; pos += len) {
        len = nr - pos; if (len > 65535) len = 65535
        push(pos + len >= nr ? 1 : 0)
        push(and(len, 255)); push(rshift(len, 8))
        push(and(xor(len, 65535), 255)); push(rshift(xor(len, 65535), 8))
        for (j = 0; j < len; j++) push(D[pos + j])
    }
    s1 = 1; s2 = 0
    for (j = 0; j < nr; j++) { s1 = (s1 + D[j]) % 65521; s2 = (s2 + s1) % 65521 }
    push32(s2 * 65536 + s1)
    chunk()
    push(73); push(69); push(78); push(68)
    chunk()
}'
}

# ── The card: corners of a 520 x 410 card with radius 30 ─────
# One 61 x 61 rounded square, cut into its four corners; the bands between them are card.png

for corner in "nw 0 0" "ne 31 0" "sw 0 31" "se 31 31"; do
    set -- $corner
    draw "$out/card_$1.png" 30 30 "$2" "$3" "$surface rect 0 0 61 61 30"
done
draw "$out/card.png" 1 1 0 0 "$surface rect -1 -1 2 2 0"

# ── The picked entry: a 44 px high rounded pill as a 9-slice ─
# A 37 x 44 shape with radius 18 (the mockup's) cut into 18 px corners and 1 px edges; GRUB
# stretches the edges and the middle around the entry. Its middle rows are straight, so the
# stretched sides meet the corners without a step.

pill="$primary rect 0 0 37 44 18"
slice() { draw "$out/select_$1.png" "$2" "$3" "$4" "$5" "$pill"; }
slice nw 18 18 0 0
slice n 1 18 18 0
slice ne 18 18 19 0
slice w 18 1 0 21
slice c 1 1 18 21
slice e 18 1 19 21
slice sw 18 18 0 26
slice s 1 18 18 26
slice se 18 18 19 26

# ── The flower: six petals round a ring, with an open middle ─

draw "$out/logo.png" 32 32 0 0 \
    "$primary disc 16 7.4 6.4" "$primary disc 23.45 11.7 6.4" "$primary disc 23.45 20.3 6.4" \
    "$primary disc 16 24.6 6.4" "$primary disc 8.55 20.3 6.4" "$primary disc 8.55 11.7 6.4" \
    "- disc 16 16 5.4" "$primary disc 16 16 3.2"

# ── The countdown ring: a track and the dots on it ───────────
# circular_progress puts the dots at radius 36 / 2 - 4 / 2 - 1 = 15, on the track's middle

draw "$out/ring_track.png" 36 36 0 0 "$high ring 18 18 15 4"
draw "$out/ring_tick.png" 4 4 0 0 "$primary disc 2 2 2"

# ── Fonts ────────────────────────────────────────────────────
# Names must match theme.txt: "Bloom Sans Regular 15", "Bloom Sans Bold 20" …; grub-mkfont
# names them family, style (Regular, or Bold with -b) and size.

font_file() {
    local f
    f=$(fc-match -f '%{file}' "$1" 2>/dev/null || true)
    [[ -n $f && $f == *"$2"* ]] && echo "$f"
    return 0
}

sans=$(font_file "Rubik" Rubik)
[[ -n $sans ]] || { echo "Rubik not found; install ttf-rubik-vf" >&2; exit 1; }
mono=$(font_file "{{fonts.mono}}" "$(echo "{{fonts.mono}}" | tr -d ' ')")
# The editor (e) and the console (c) want a fixed width; Rubik when the mono font is missing
[[ -n $mono ]] || mono=$(font_file "JetBrains Mono" JetBrains)
[[ -n $mono ]] || mono=$sans

grub-mkfont -n "Bloom Sans" -s 13 -o "$out/bloom-regular-13.pf2" "$sans"
grub-mkfont -n "Bloom Sans" -s 15 -o "$out/bloom-regular-15.pf2" "$sans"
grub-mkfont -n "Bloom Sans" -b -s 13 -o "$out/bloom-bold-13.pf2" "$sans"
grub-mkfont -n "Bloom Sans" -b -s 20 -o "$out/bloom-bold-20.pf2" "$sans"
grub-mkfont -n "Bloom Mono" -s 15 -o "$out/bloom-mono-15.pf2" "$mono"
